export class BatchQueue {
    #elements = [];
    #batches = [];
    #batch = 1;

    get size() {
        return this.#elements.length;
    }

    get batch() {
        return this.#batch;
    }

    set batch(value) {
        this.#batch = value;
    }

    offer(element) {
        this.#elements.push(element);
        this.#batches.push(this.#batch);
    }

    clearToBatch(batch) {
        let deleteCount = 0;
        for (let i = 0; i < this.#elements.length; ++i) {
            if (this.#batches[i] > batch) {
                break;
            }
            ++deleteCount;
        }
        this.#elements.splice(0, deleteCount);
        this.#batches.splice(0, deleteCount);
    }

    sliceToBatch(batch) {
        const result = [];
        for (let i = 0; i < this.#elements.length; ++i) {
            if (this.#batches[i] > batch) {
                break;
            }
            result.push(this.#elements[i]);
        }
        return result;
    }
}
